"""

import re
import subprocess

from .errors import ICaclsError

#: icacls 可执行文件名。
ICACLS = "icacls"

#: 只在目录上有意义的继承标志，不参与权限集合。
_INHERITANCE_FLAGS = frozenset({"OI", "CI", "IO", "NP"})

_ACE_RE = re.compile(r"^\s*(.+?):((?:\([^)]*\))+)\s*$")
_TOKEN_RE = re.compile(r"\(([^)]*)\)")

#: icacls 把目标路径回显在首行行首，形如 ``C:\\dir BUILTIN\\Users:(RX)``。
_PATH_RE = re.compile(r"^(?:[A-Za-z]:[\\/]|\\\\)")


class Ace(object):
    """一条访问控制项。"""

    __slots__ = ("principal", "rights", "deny", "inherited")

    def __init__(self, principal, rights, deny=False, inherited=False):
        self.principal = principal
        self.rights = frozenset(rights)
        self.deny = deny
        self.inherited = inherited

    def __repr__(self):
        return "Ace(%r, %r, deny=%r, inherited=%r)" % (
            self.principal,
            sorted(self.rights),
            self.deny,
            self.inherited,
        )


def run(path, *args):
    """对 ``path`` 执行 icacls，返回标准输出。"""
    cmd = [ICACLS, path] + [str(a) for a in args]
    proc = subprocess.run(cmd, capture_output=True, text=True)
    if proc.returncode != 0:
        raise ICaclsError(
            "icacls %s failed with %d: %s" % (path, proc.returncode, _detail(proc))
        )
    return proc.stdout


def _detail(proc):
    """把 icacls 的报错内容拼成一行，便于排错。"""
    parts = [(proc.stdout or "").strip(), (proc.stderr or "").strip()]
    return " / ".join(part for part in parts if part)


def _indent_of(line):
    return len(line) - len(line.lstrip())


def _ace_column(lines):
    """返回续行 ACE 的对齐列，也就是首行里目标路径占掉的宽度。

    ``icacls`` 把首条 ACE 与路径打印在同一行，其余 ACE 一律缩进到路径之后
    的同一列，因此这一列正好是首行里需要跳过的前缀长度。
    """
    columns = [_indent_of(line) for line in lines if _indent_of(line) and _ACE_RE.match(line)]
    return min(columns) if columns else 0


def _drop_path_prefix(line, column):
    """去掉首行里 icacls 回显的目标路径，只留下 ``principal:(...)``。

    路径里可以有空格，主体名里也可能有空格（例如 ``NT AUTHORITY\\SYSTEM``），
    所以优先按续行的对齐列切；只有一条 ACE、无从对齐时才退化为「取冒号前
    最后一个词」。
    """
    if not _PATH_RE.match(line):
        return line
    if column and len(line) > column:
        head = line[:column]
        if head.strip() and head[-1] in " \t":
            return line[column:]
    matched = _ACE_RE.match(line)
    if matched and " " in matched.group(1):
        tail = matched.group(1).rsplit(" ", 1)[1]
        return line[len(matched.group(1)) - len(tail):]
    return line


def parse_aces(output):
    """把 icacls 的输出解析成 :class:`Ace` 列表。

    ``(I)`` 表示该项是从父级继承来的，``(DENY)`` 表示拒绝项，``(OI)``/``(CI)``
    等只是继承标志、不属于权限本身。
    """
    lines = output.splitlines()
    column = _ace_column(lines)
    aces = []
    for line in lines:
        m = _ACE_RE.match(_drop_path_prefix(line, column))
        if not m:
            continue
        principal = m.group(1).strip()
        tokens = [
            token.strip().upper()
            for group in _TOKEN_RE.findall(m.group(2))
            for token in group.split(",")
        ]
        deny = "DENY" in tokens
        inherited = "I" in tokens
        rights = {
            t for t in tokens if t and t not in _INHERITANCE_FLAGS and t not in ("DENY", "I")
        }
        if not rights:
            continue
        aces.append(Ace(principal, rights, deny=deny, inherited=inherited))
    return aces


def list_aces(path):
    """返回 ``path`` 上的全部访问控制项（含从父级继承来的）。"""
    return parse_aces(run(path))


def list_explicit_aces(path):
    """返回 ``path`` 上**显式设置**的访问控制项。

    从父目录继承来的项不算显式设置：icacls 会给它们打上 ``(I)`` 标记，
    这里据此把它们过滤掉，免得审计报表把继承项当成本目录上显式授予的权限。
    """
    return [ace for ace in list_aces(path) if not ace.inherited]


def deny(path, principal, spec, recursive=False):
    """在 ``path`` 上为主体添加一条拒绝项。

    ``spec`` 是 icacls 的权限说明，例如 ``"(OI)(CI)(RX)"``。
    ``recursive`` 为真时附加 ``/T``，让整棵子树里已经存在的条目也拿到这一项。
    """
    args = ["/deny", "%s:%s" % (principal, spec)]
    if recursive:
        args.append("/T")
    return run(path, *args)


def grant(path, principal, spec, recursive=False):
    """在 ``path`` 上为主体添加一条允许项。"""
    args = ["/grant", "%s:%s" % (principal, spec)]
    if recursive:
        args.append("/T")
    return run(path, *args)


def disable_inheritance(path):
    """移除 ``path`` 上从父目录继承来的项。"""
    return run(path, "/inheritance:r")

"""有效权限判定。

Windows 的访问控制模型里，**显式拒绝优先于允许**：只要有一条拒绝项命中，
该权限就是不予授予，哪怕同时存在允许项。
"""

from .icacls import list_aces

#: 表示「可写」的权限字母。
WRITE_RIGHTS = frozenset({"W", "M", "F"})

#: 表示「可读」的权限字母（写与完全控制都隐含读）。
READ_RIGHTS = frozenset({"R", "RX", "F", "M", "W"})


def _canonical(principal):
    """把主体名规整成可比较的形式。

    icacls 既接受 ``*S-1-5-32-546`` 这样的字面 SID，也接受 ``BUILTIN\\Guests``
    这样的名字，回显时却只保留其中一种；比较前去掉字面 SID 的星号前缀并统一
    大小写，免得同一个主体被判成两个。
    """
    name = (principal or "").strip()
    if name.startswith("*"):
        name = name[1:]
    return name.upper()


def _same_principal(left, right):
    return _canonical(left) == _canonical(right)


def effective_rights(path, principal):
    """返回 ``principal`` 在 ``path`` 上被允许与被拒绝的权限集合。"""
    allow = set()
    deny = set()
    for ace in list_aces(path):
        if not _same_principal(ace.principal, principal):
            continue
        if ace.deny:
            deny |= ace.rights
        else:
            allow |= ace.rights
    return allow, deny


def can_write(path, principal):
    """``principal`` 能否在 ``path`` 上写入。

    拒绝优先：命中写权限的拒绝项时一律返回 ``False``，即使同时存在允许项。
    """
    allow, deny = effective_rights(path, principal)
    if deny & WRITE_RIGHTS:
        return False
    return bool(allow & WRITE_RIGHTS)


def can_read(path, principal):
    """``principal`` 能否在 ``path`` 上读取。"""
    allow, deny = effective_rights(path, principal)
    if deny & READ_RIGHTS:
        return False
    return bool(allow & READ_RIGHTS)
